// A tiny todo list with due dates, priorities and JSON persistence.
import { readFileSync, writeFileSync } from "node:fs";

export const PRIORITIES = ["low", "normal", "high"];

function parseDue(due) {
  if (due === undefined || due === null) return null;
  const d = due instanceof Date ? due : new Date(due);
  if (Number.isNaN(d.getTime())) throw new Error("invalid due date");
  return d.toISOString();
}

export class TodoList {
  constructor() { this.items = []; this.nextId = 1; }

  add(title, { due, priority = "normal" } = {}) {
    if (!title) throw new Error("title is required");
    if (!PRIORITIES.includes(priority)) throw new Error(`invalid priority: ${priority}`);
    const item = { id: this.nextId++, title, done: false, due: parseDue(due), priority };
    this.items.push(item);
    return item;
  }

  complete(id) {
    const item = this.items.find(i => i.id === id);
    if (!item) throw new Error(`item ${id} not found`);
    item.done = true;
    return item;
  }

  pending() {
    return this.items.filter(i => !i.done);
  }

  clear() {
    this.items = this.items.filter(i => !i.done);
  }

  // Overdue first, then priority (high to low), then due date (none last), then id.
  sorted(now = new Date()) {
    const t = new Date(now).getTime();
    const overdue = i => !i.done && i.due !== null && new Date(i.due).getTime() < t;
    const dueTime = i => (i.due === null ? Infinity : new Date(i.due).getTime());
    return [...this.items].sort((a, b) =>
      overdue(b) - overdue(a) ||
      PRIORITIES.indexOf(b.priority) - PRIORITIES.indexOf(a.priority) ||
      (dueTime(a) === dueTime(b) ? 0 : dueTime(a) < dueTime(b) ? -1 : 1) ||
      a.id - b.id);
  }

  save(path) {
    writeFileSync(path, JSON.stringify({ nextId: this.nextId, items: this.items }, null, 2));
  }

  static load(path) {
    const data = JSON.parse(readFileSync(path, "utf8"));
    const list = new TodoList();
    list.items = data.items.map(i => ({
      done: false, due: null, priority: "normal", ...i,
    }));
    list.nextId = Math.max(data.nextId ?? 1, ...list.items.map(i => i.id + 1));
    return list;
  }
}
