import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execFileSync } from "node:child_process";

function setup() {
  const dir = mkdtempSync(join(tmpdir(), "todo-cli-"));
  const env = { ...process.env, TODO_FILE: join(dir, "t.json") };
  const run = (...args) => execFileSync("node", ["bin/todo.js", ...args], { env, encoding: "utf8", stdio: "pipe" });
  const lines = out => out.trim().split(/\r?\n/).filter(Boolean);
  return { run, lines, cleanup: () => rmSync(dir, { recursive: true }) };
}

test("cli tag and list --tag", () => {
  const { run, lines, cleanup } = setup();
  try {
    run("add", "buy milk");
    run("add", "walk dog");
    run("tag", "1", "Home");
    const out = lines(run("list", "--tag", "home"));
    assert.equal(out.length, 1);
    assert.match(out[0], /^1 .*buy milk/);
    assert.equal(lines(run("list", "--tag", "work")).length, 0);
    run("untag", "1", "home");
    assert.equal(lines(run("list", "--tag", "home")).length, 0);
    assert.throws(() => run("tag", "99", "x"));
  } finally { cleanup(); }
});

test("cli search", () => {
  const { run, lines, cleanup } = setup();
  try {
    run("add", "buy milk");
    run("add", "walk dog");
    run("tag", "2", "pets");
    assert.match(run("search", "MILK"), /buy milk/);
    const out = lines(run("search", "pets"));
    assert.equal(out.length, 1);
    assert.match(out[0], /walk dog/);
    assert.equal(lines(run("search", "nothing")).length, 0);
    assert.throws(() => run("search"));
  } finally { cleanup(); }
});

test("cli done", () => {
  const { run, cleanup } = setup();
  try {
    run("add", "buy milk");
    assert.match(run("done", "1"), /completed 1: buy milk/);
    assert.match(run("list"), /^1 \[x\]/);
    assert.throws(() => run("done", "7"));
  } finally { cleanup(); }
});

test("cli recur", () => {
  const { run, cleanup } = setup();
  try {
    run("add", "water plants");
    assert.match(run("recur", "1", "weekly"), /recurrence for 1: weekly/);
    assert.match(run("export", "--json"), /weekly/);
    run("recur", "1", "none");
    assert.throws(() => run("recur", "1", "hourly"));
    assert.throws(() => run("recur", "99", "daily"));
  } finally { cleanup(); }
});

test("cli export --json", () => {
  const { run, cleanup } = setup();
  try {
    run("add", "buy milk", "--priority", "high");
    run("tag", "1", "home");
    const items = JSON.parse(run("export", "--json"));
    assert.equal(items.length, 1);
    assert.equal(items[0].title, "buy milk");
    assert.equal(items[0].priority, "high");
    assert.deepEqual(items[0].tags, ["home"]);
  } finally { cleanup(); }
});

test("cli export --csv escapes quotes, commas and newlines", () => {
  const { run, lines, cleanup } = setup();
  try {
    run("add", 'say "hi", then\nleave');
    run("add", "plain");
    assert.throws(() => run("export"));
    const out = run("export", "--csv");
    assert.match(out, /^id,title,done,due,priority,tags,recurrence\n/);
    assert.ok(out.includes('1,"say ""hi"", then\nleave",false,'));
    assert.match(out, /\n2,plain,false,,normal,/);
    assert.equal(lines(out).length, 4);
  } finally { cleanup(); }
});

